import { ValidationFunction } from './validation-function';
export interface Validator {
    execute: ValidationFunction;
    /**
     * This holds the bit of information the rule needs to do validation.
     * Ex: maxLength: 10 - condition is set to 10
     * Ex: maxValue: new Date('5/25/1977') - condition is set to new Date('5/25/1977')
     */
    condition?: any;
}
